import { db } from "../firebase"; // Import Firebase config
import { collection, getDocs } from "firebase/firestore";

// 🔹 Fetch Carbon Data from Firebase
export const fetchCarbonData = async () => {
  try {
    const querySnapshot = await getDocs(collection(db, "carbon-emissions"));
    return querySnapshot.docs.map((doc) => doc.data());
  } catch (error) {
    console.error("Error fetching carbon data:", error);
    return [];
  }
};

// 🔹 Calculate Monthly Averages (X-axis: Months, Y-axis: Averages)
export const calculateMonthlyAverages = async () => {
  const data = await fetchCarbonData(); // Fetch data first

  const monthlySums = {};
  const monthlyCounts = {};

  data.forEach((record) => {
    if (record.createdAt && record.totalCarbon) {
      const date = record.createdAt.toDate(); // Convert Firestore Timestamp to Date
      const month = date.getMonth(); // Get month index (0 = Jan, ..., 11 = Dec)

      if (!monthlySums[month]) {
        monthlySums[month] = 0;
        monthlyCounts[month] = 0;
      }

      monthlySums[month] += record.totalCarbon;
      monthlyCounts[month] += 1;
    }
  });

  // Return an array of monthly averages from Jan to Dec
  return Array.from({ length: 12 }, (_, i) =>
    monthlyCounts[i] > 0 ? monthlySums[i] / monthlyCounts[i] : 0
  );
};
